const n_Assemble_market = node({ type: "n8n-nodes-base.code", version: 2, config: {"name": "Assemble market", "parameters": {"jsCode": "// Assemble market (Code, run once for all items). Input: Merge market (the Offering and Topic researchers' checked\n// answers, or their stubs). Keeps the slides that found something, offering first.\n// A row reaches the deck only when its context and its action each cite a source in that slide's source list:\n// a figure with no source reads as invented. Uncited rows are left out with a warning (run 152, Oct 16: the\n// Topic researcher returned four rows with figures and an empty source list).\nconst items = $input.all();\nconst order = { market_context_offering: 0, market_context_topic: 1 };\nconst kept = [];\nconst warnings = [];\nfor (const it of items) {\n  const o = (it.json && it.json.output) || {};\n  const slide = o.slide || {};\n  const skipped = it.json && it.json._skipped;\n  if (skipped || !Array.isArray(slide.rows) || slide.rows.length === 0 || o.search_quality === 'none') continue;\n  const listed = new Set((o.sources || []).map(s => s && s.ref).filter(x => x != null));\n  const cites = p => !!p && Array.isArray(p.refs) && p.refs.some(x => listed.has(x));\n  const rows = slide.rows.filter(r => r && cites(r.context) && cites(r.action));\n  if (rows.length < slide.rows.length) {\n    warnings.push(`Market research (${slide.slide_id}): ${slide.rows.length - rows.length} of ${slide.rows.length} finding(s) left out because they cite no listed source.`);\n  }\n  if (!rows.length) continue;\n  // The title states what the rows share. Rows across several dimensions share nothing, and the researcher's title then\n  // says so ('three sources show trends'); the strongest row's headline carries the slide instead (Sequence 1, Oct 25).\n  const dims = new Set(rows.map(r => r.dimension));\n  const title = (dims.size > 1 && rows[0].summary) ? String(rows[0].summary).trim().replace(/[.]$/, '').slice(0, 90) : slide.title;\n  kept.push({ ...o, slide: { ...slide, rows, title, title_source: dims.size > 1 && rows[0].summary ? 'code' : 'researcher' } });\n}\nkept.sort((a, b) => { const oa = order[a.slide.slide_id]; const ob = order[b.slide.slide_id]; return (oa === undefined ? 9 : oa) - (ob === undefined ? 9 : ob); });\nconst market_slides = kept.map(o => ({ slide: o.slide, sources: o.sources || [] }));\nconst market_findings = [];\nfor (const o of kept) {\n  for (const r of o.slide.rows) {\n    market_findings.push({ actor: r.actor, dimension: r.dimension, summary: r.summary, scope_risk: r.scope_risk, why_it_matters_to_scope: r.why_it_matters_to_scope });\n  }\n}\nreturn [{ json: { market_slides: market_slides, market_slide_count: market_slides.length, market_findings: market_findings, market_warnings: warnings } }];\n"}}, output: [{}] });
const n_Research_report = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Research report', parameters: { jsCode: "// Research report (Code, run once). A readable view of what the research stage produced: one line per row, the\n// not-covered list, the claims, the retry routes and the budget, so a run can be judged without opening the JSON.\nconst A = $input.first().json;\nconst md = [];\nmd.push(`# Research stage report: ${$('Test case').first().json.case} (${$('Config').first().json.today})`);\nfor (const s of (A.market_slides || [])) {\n  const sl = s.slide || {};\n  md.push(`\\n## ${sl.slide_id}: ${sl.title} (title by ${sl.title_source || '-'})`);\n  md.push(`| # | Actor | Type | Dimension | Summary | Risk | Date | Source |\\n|---|---|---|---|---|---|---|---|`);\n  (sl.rows || []).forEach((r, i) => { const ref = ((r.action || {}).refs || [])[0]; const src = (s.sources || []).find(x => x.ref === ref) || {}; md.push(`| ${i + 1} | ${r.actor} | ${r.actor_type} | ${r.dimension} | ${r.summary} | ${r.scope_risk} | ${src.source_date || src.date || '-'} | ${src.source_url || ''} |`); });\n  if ((sl.not_covered || []).length) md.push(`\\nNot covered: ${sl.not_covered.join('; ')}`);\n}\nconst passes = {};\nfor (const [chk, name] of [['Check offering', 'offering'], ['Check topic', 'topic']]) { const runs = []; for (let k = 0; k < 3; k++) { try { const a = $(chk).all(0, k); if (!a || !a.length) break; runs.push(a[0].json); } catch (e) { break; } } if (runs.length) passes[name] = runs.map(r => ({ route: r._route, rows: (((r.output || {}).slide || {}).rows || []).length, violations: ((r._research_validation || {}).violations || []).length, budget: { searches: (r._research_validation || {}).searches_used, reads: (r._research_validation || {}).reads_used } })); }\nmd.push(`\\n## Passes\\n` + Object.entries(passes).map(([k, v]) => `- ${k}: ` + v.map((p, i) => `pass ${i + 1} route ${p.route}, ${p.rows} rows, ${p.violations} violations, budget ${JSON.stringify(p.budget)}`).join('; ')).join('\\n'));\nif ((A.market_warnings || []).length) md.push(`\\n## Warnings\\n` + A.market_warnings.map(x => `- ${typeof x === 'string' ? x : JSON.stringify(x)}`).join('\\n'));\nconst claims = (($('Research brief').first().json || {}).research_brief || {}).claims || [];\nif (claims.length) md.push(`\\n## Claims from the brief\\n` + claims.map(c => `- ${c.id || ''}: ${c.text || JSON.stringify(c)}`).join('\\n'));\nreturn [{ json: { ...A, report_markdown: md.join('\\n') } }];" } }, output: [{}] });
